        if (exponent % 2 == 1) {
            x = (x * y) % mod;
        }
        y = (y * y) % mod;
        exponent = Math.floor(exponent / 2);
    }
    return x % mod;
}

// To calculate Jacobian symbol of a given number
function calculateJacobian(a, n) {
    if (n <= 0 || n % 2 == 0) {
        return 0;
    }

    let ans = 1;
    if (a < 0) {
        a = -a;
        if (n % 4 == 3) {
            ans = -ans;
        }
    }

    if (a == 1) {
        return ans;
    }

    while (a !== 0) {
        if (a < 0) {
            a = -a;
            if (n % 4 == 3) {
                ans = -ans;
            }
        }

        while (a % 2 == 0) {
            a = Math.floor(a / 2);
            if (n % 8 == 3 || n % 8 == 5) {
                ans = -ans;
            }
        }

        let temp = a;
        a = n;
        n = temp;

        if (a % 4 == 3 && n % 4 == 3) {
            ans = -ans;
        }

        a %= n;
        if (a > Math.floor(n / 2)) {
            a -= n;
        }
    }

    return n === 1 ? ans : 0;
}

// To perform the Solovay-Strassen Primality Test
function solovoyStrassen(p, iteration) {
    if (p < 2 || (p % 2 === 0 && p !== 2)) {
        return false;
    }

    for (let i = 0; i < iteration; i++) {
        let a = Math.floor(Math.random() * (p - 2)) + 1;
        let jacobian = (p + calculateJacobian(a, p)) % p;
        let mod = modulo(a, Math.floor((p - 1) / 2), p);

        if (jacobian === 0 || mod !== jacobian) {
            return false;
        }
    }
    return true;
}

